ALTER TABLE public.profiles ADD COLUMN debe_cambiar_password boolean NOT NULL DEFAULT false;
CREATE TABLE public.password_cambios (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, password_anterior text NOT NULL);
GRANT ALL ON public.password_cambios TO service_role;
ALTER TABLE public.password_cambios ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.profiles TO authenticated;
CREATE OR REPLACE FUNCTION public.estado_acceso_personal() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE u record; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF; SELECT coalesce(encrypted_password,'')<>'' AS tiene, last_sign_in_at IS NOT NULL AS accedido INTO u FROM auth.users WHERE id=auth.uid(); RETURN jsonb_build_object('tiene_password',u.tiene,'ha_accedido',u.accedido,'debe_cambiar_password',coalesce((SELECT debe_cambiar_password FROM public.profiles WHERE id=auth.uid()),false)); END $$;
REVOKE ALL ON FUNCTION public.estado_acceso_personal() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.estado_acceso_personal() TO authenticated;
CREATE OR REPLACE FUNCTION public.preparar_password_usuario(p_email text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid; BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; IF NOT EXISTS(SELECT 1 FROM public.usuario_roles WHERE email=lower(trim(p_email)) AND activo) THEN RAISE EXCEPTION 'Persona no disponible'; END IF; SELECT id INTO u FROM auth.users WHERE lower(email)=lower(trim(p_email)) LIMIT 1; RETURN u; END $$;
REVOKE ALL ON FUNCTION public.preparar_password_usuario(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.preparar_password_usuario(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.registrar_password_usuario(p_actor uuid,p_usuario uuid,p_email text,p_accion text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.usuario_roles WHERE user_id=p_actor AND activo AND rol='super_admin') THEN RAISE EXCEPTION 'Solo Super admin'; END IF; IF p_accion NOT IN ('password_inicial','password_cambiada_admin') OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_usuario AND lower(email)=lower(trim(p_email)) AND email_confirmed_at IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM public.usuario_roles WHERE email=lower(trim(p_email)) AND activo) THEN RAISE EXCEPTION 'No autorizado'; END IF; INSERT INTO public.profiles(id,email) VALUES(p_usuario,lower(trim(p_email))) ON CONFLICT(id) DO NOTHING; UPDATE public.profiles SET debe_cambiar_password=true WHERE id=p_usuario; INSERT INTO public.password_cambios(user_id,password_anterior) SELECT id,encrypted_password FROM auth.users WHERE id=p_usuario ON CONFLICT(user_id) DO UPDATE SET password_anterior=excluded.password_anterior; UPDATE public.usuario_roles SET user_id=p_usuario WHERE email=lower(trim(p_email)) AND activo; INSERT INTO public.registro_permisos(actor_id,afectado_id,accion,motivo) VALUES(p_actor,p_usuario,p_accion,'Contraseña gestionada por Super admin'); END $$;
REVOKE ALL ON FUNCTION public.registrar_password_usuario(uuid,uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.registrar_password_usuario(uuid,uuid,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.completar_cambio_password() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF; IF EXISTS(SELECT 1 FROM public.password_cambios c JOIN auth.users u ON u.id=c.user_id WHERE c.user_id=auth.uid() AND (coalesce(u.encrypted_password,'')='' OR u.encrypted_password=c.password_anterior)) THEN RAISE EXCEPTION 'Guarda primero tu nueva contraseña'; END IF; UPDATE public.profiles SET debe_cambiar_password=false WHERE id=auth.uid(); DELETE FROM public.password_cambios WHERE user_id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.completar_cambio_password() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.completar_cambio_password() TO authenticated;